function readDocument(actor, input, documents) {
  if (!actor) throw new Error("unauthorized");
  const document = documents.find((entry) => entry.id === input.id);
  if (!document || document.tenantId !== actor.tenantId) throw new Error("not found");
  return document.body;
}

